package org.joda.time;

import org.junit.Test;
import static org.junit.Assert.*;

public class DateMidnightTest {

    @Test
    public void testNow() {
        DateMidnight now = DateMidnight.now();
        assertNotNull(now);
        assertEquals(now.getMillis(), DateTimeUtils.currentTimeMillis());
    }

    @Test
    public void testNowWithZone() {
        DateTimeZone zone = DateTimeZone.UTC;
        DateMidnight now = DateMidnight.now(zone);
        assertNotNull(now);
        assertEquals(zone, now.getZone());
    }

    @Test(expected = NullPointerException.class)
    public void testNowWithNullZone() {
        DateMidnight.now(null);
    }

    @Test
    public void testNowWithChronology() {
        Chronology chrono = ISOChronology.getInstanceUTC();
        DateMidnight now = DateMidnight.now(chrono);
        assertNotNull(now);
        assertEquals(chrono, now.getChronology());
    }

    @Test(expected = NullPointerException.class)
    public void testNowWithNullChronology() {
        DateMidnight.now(null);
    }

    @Test
    public void testParse() {
        String dateStr = "2023-01-01";
        DateMidnight parsed = DateMidnight.parse(dateStr);
        assertNotNull(parsed);
        assertEquals(2023, parsed.getYear());
        assertEquals(1, parsed.getMonthOfYear());
        assertEquals(1, parsed.getDayOfMonth());
    }

    @Test
    public void testParseWithFormatter() {
        String dateStr = "01/01/2023";
        DateTimeFormatter formatter = DateTimeFormat.forPattern("dd/MM/yyyy");
        DateMidnight parsed = DateMidnight.parse(dateStr, formatter);
        assertNotNull(parsed);
        assertEquals(2023, parsed.getYear());
        assertEquals(1, parsed.getMonthOfYear());
        assertEquals(1, parsed.getDayOfMonth());
    }

    @Test
    public void testConstructorWithInstant() {
        long instant = System.currentTimeMillis();
        DateMidnight dateMidnight = new DateMidnight(instant);
        assertNotNull(dateMidnight);
        assertEquals(instant, dateMidnight.getMillis());
    }

    @Test
    public void testConstructorWithInstantAndZone() {
        long instant = System.currentTimeMillis();
        DateTimeZone zone = DateTimeZone.UTC;
        DateMidnight dateMidnight = new DateMidnight(instant, zone);
        assertNotNull(dateMidnight);
        assertEquals(instant, dateMidnight.getMillis());
        assertEquals(zone, dateMidnight.getZone());
    }

    @Test
    public void testConstructorWithInstantAndChronology() {
        long instant = System.currentTimeMillis();
        Chronology chrono = ISOChronology.getInstanceUTC();
        DateMidnight dateMidnight = new DateMidnight(instant, chrono);
        assertNotNull(dateMidnight);
        assertEquals(instant, dateMidnight.getMillis());
        assertEquals(chrono, dateMidnight.getChronology());
    }

    @Test
    public void testConstructorWithYearMonthDay() {
        DateMidnight dateMidnight = new DateMidnight(2023, 1, 1);
        assertNotNull(dateMidnight);
        assertEquals(2023, dateMidnight.getYear());
        assertEquals(1, dateMidnight.getMonthOfYear());
        assertEquals(1, dateMidnight.getDayOfMonth());
    }

    @Test
    public void testConstructorWithYearMonthDayAndZone() {
        DateTimeZone zone = DateTimeZone.UTC;
        DateMidnight dateMidnight = new DateMidnight(2023, 1, 1, zone);
        assertNotNull(dateMidnight);
        assertEquals(2023, dateMidnight.getYear());
        assertEquals(1, dateMidnight.getMonthOfYear());
        assertEquals(1, dateMidnight.getDayOfMonth());
        assertEquals(zone, dateMidnight.getZone());
    }

    @Test
    public void testConstructorWithYearMonthDayAndChronology() {
        Chronology chrono = ISOChronology.getInstanceUTC();
        DateMidnight dateMidnight = new DateMidnight(2023, 1, 1, chrono);
        assertNotNull(dateMidnight);
        assertEquals(2023, dateMidnight.getYear());
        assertEquals(1, dateMidnight.getMonthOfYear());
        assertEquals(1, dateMidnight.getDayOfMonth());
        assertEquals(chrono, dateMidnight.getChronology());
    }

    @Test
    public void testWithMillis() {
        long originalMillis = System.currentTimeMillis();
        DateMidnight original = new DateMidnight(originalMillis);
        long newMillis = originalMillis + 86400000; // Add 1 day
        DateMidnight newDateMidnight = original.withMillis(newMillis);
        assertNotNull(newDateMidnight);
        assertEquals(newMillis, newDateMidnight.getMillis());
        assertNotSame(original, newDateMidnight);
    }

    @Test
    public void testWithChronology() {
        DateMidnight original = DateMidnight.now();
        Chronology newChronology = ISOChronology.getInstanceUTC();
        DateMidnight newDateMidnight = original.withChronology(newChronology);
        assertNotNull(newDateMidnight);
        assertEquals(newChronology, newDateMidnight.getChronology());
        assertNotSame(original, newDateMidnight);
    }

    @Test
    public void testWithZoneRetainFields() {
        DateTimeZone originalZone = DateTimeZone.getDefault();
        DateMidnight original = DateMidnight.now();
        DateTimeZone newZone = DateTimeZone.UTC;
        DateMidnight newDateMidnight = original.withZoneRetainFields(newZone);
        assertNotNull(newDateMidnight);
        assertEquals(newZone, newDateMidnight.getZone());
        assertEquals(original.getYear(), newDateMidnight.getYear());
        assertEquals(original.getMonthOfYear(), newDateMidnight.getMonthOfYear());
        assertEquals(original.getDayOfMonth(), newDateMidnight.getDayOfMonth());
        assertNotSame(original, newDateMidnight);
    }

    @Test
    public void testWithFields() {
        DateMidnight original = DateMidnight.now();
