        assertNotNull(newDateMidnight);
        assertEquals(2023, newDateMidnight.getYear());
        assertEquals(1, newDateMidnight.getMonthOfYear());
        assertEquals(1, newDateMidnight.getDayOfMonth());
        assertNotSame(original, newDateMidnight);
    }

