package org.joda.time;

import org.junit.Test;
import static org.junit.Assert.*;

public class DateTimeTest {

    @Test
    public void testNow() {
        DateTime now = DateTime.now();
        assertNotNull(now);
        assertTrue(now.getMillis() <= System.currentTimeMillis());
    }

    @Test
    public void testNowWithZone() {
        DateTimeZone zone = DateTimeZone.UTC;
        DateTime now = DateTime.now(zone);
        assertNotNull(now);
        assertEquals(zone, now.getZone());
    }

    @Test
    public void testNowWithChronology() {
        Chronology chrono = ISOChronology.getInstanceUTC();
        DateTime now = DateTime.now(chrono);
        assertNotNull(now);
        assertEquals(chrono, now.getChronology());
    }

    @Test
    public void testParse() {
        String dateStr = "2023-01-01T00:00:00.000Z";
        DateTime parsed = DateTime.parse(dateStr);
        assertNotNull(parsed);
        assertEquals(2023, parsed.getYear());
        assertEquals(1, parsed.getMonthOfYear());
        assertEquals(1, parsed.getDayOfMonth());
        assertEquals(0, parsed.getHourOfDay());
        assertEquals(0, parsed.getMinuteOfHour());
        assertEquals(0, parsed.getSecondOfMinute());
        assertEquals(0, parsed.getMillisOfSecond());
    }

