public class DateTimeComparatorTest {

    private DateTimeComparator allComparator;
    private DateTimeComparator dateOnlyComparator;
    private DateTimeComparator timeOnlyComparator;
    private DateTimeComparator customComparator;

    @Before
    public void setUp() {
        allComparator = DateTimeComparator.getInstance();
        dateOnlyComparator = DateTimeComparator.getDateOnlyInstance();
        timeOnlyComparator = DateTimeComparator.getTimeOnlyInstance();
        customComparator = DateTimeComparator.getInstance(DateTimeFieldType.dayOfYear(), DateTimeFieldType.hourOfDay());
    }

    @Test
    public void testGetInstance() {
        assertEquals(DateTimeComparator.ALL_INSTANCE, DateTimeComparator.getInstance());
    }

    @Test
    public void testGetDateOnlyInstance() {
        assertEquals(DateTimeComparator.DATE_INSTANCE, DateTimeComparator.getDateOnlyInstance());
    }

    @Test
    public void testGetTimeOnlyInstance() {
        assertEquals(DateTimeComparator.TIME_INSTANCE, DateTimeComparator.getTimeOnlyInstance());
    }

    @Test
    public void testGetInstanceWithLowerLimit() {
        DateTimeComparator comparator = DateTimeComparator.getInstance(DateTimeFieldType.dayOfYear());
        assertEquals(DateTimeComparator.DATE_INSTANCE, comparator);
    }

    @Test
    public void testGetInstanceWithUpperLimit() {
        DateTimeComparator comparator = DateTimeComparator.getInstance(null, DateTimeFieldType.hourOfDay());
        assertEquals(DateTimeComparator.TIME_INSTANCE, comparator);
    }

    @Test
    public void testGetInstanceWithBothLimits() {
        DateTimeComparator comparator = DateTimeComparator.getInstance(
            DateTimeFieldType.dayOfYear(), DateTimeFieldType.hourOfDay());
        assertEquals(customComparator, comparator);
    }

    @Test
    public void testCompareSameObject() {
        DateTime date = new DateTime();
        assertEquals(0, allComparator.compare(date, date));
    }

    @Test
    public void testCompareNullWithNull() {
        assertEquals(0, allComparator.compare(null, null));
    }

    @Test
    public void testCompareDifferentDates() {
        DateTime date1 = new DateTime(2020, 1, 1, 0, 0);
        DateTime date2 = new DateTime(2020, 1, 2, 0, 0);
        assertEquals(-1, allComparator.compare(date1, date2));
        assertEquals(1, allComparator.compare(date2, date1));
    }

    @Test
    public void testCompareSameDateDifferentTime() {
        DateTime date1 = new DateTime(2020, 1, 1, 0, 0);
        DateTime date2 = new DateTime(2020, 1, 1, 1, 0);
        assertEquals(-1, allComparator.compare(date1, date2));
        assertEquals(1, allComparator.compare(date2, date1));
    }

    @Test
    public void testCompareSameDateSameTime() {
        DateTime date1 = new DateTime(2020, 1, 1, 0, 0);
        DateTime date2 = new DateTime(2020, 1, 1, 0, 0);
        assertEquals(0, allComparator.compare(date1, date2));
    }

