        DateTime date2 = new DateTime(2020, 1, 1, 12, 0);
        assertEquals(0, dateOnlyComparator.compare(date1, date2));
    }

    @Test
    public void testCompareTimeOnly() {
        DateTime date1 = new DateTime(2020, 1, 1, 0, 0);
        DateTime date2 = new DateTime(2020, 1, 2, 0, 0);
        assertEquals(0, timeOnlyComparator.compare(date1, date2));
    }

    @Test
    public void testCompareCustomRange() {
        DateTime date1 = new DateTime(2020, 1, 1, 0, 0);
        DateTime date2 = new DateTime(2020, 1, 2, 0, 0);
        assertEquals(-1, customComparator.compare(date1, date2));

        date1 = new DateTime(2020, 1, 1, 0, 0);
        date2 = new DateTime(2020, 1, 1, 12, 0);
        assertEquals(0, customComparator.compare(date1, date2));

        date1 = new DateTime(2020, 1, 1, 0, 0);
        date2 = new DateTime(2020, 1, 1, 23, 59);
        assertEquals(-1, customComparator.compare(date1, date2));
    }

    @Test
    public void testCompareWithDifferentTimeZones() {
        DateTime date1 = new DateTime(2020, 1, 1, 0, 0, DateTimeZone.forID("America/New_York"));
        DateTime date2 = new DateTime(2020, 1, 1, 0, 0, DateTimeZone.forID("Europe/London"));
        assertEquals(-1, allComparator.compare(date1, date2));
    }

    @Test
    public void testCompareWithNull() {
        DateTime date = new DateTime();
        assertEquals(-1, allComparator.compare(date, null));
        assertEquals(1, allComparator.compare(null, date));
    }

    @Test
    public void testGetLowerLimit() {
        assertNull(allComparator.getLowerLimit());
        assertEquals(DateTimeFieldType.dayOfYear(), dateOnlyComparator.getLowerLimit());
        assertNull(timeOnlyComparator.getLowerLimit());
        assertEquals(DateTimeFieldType.dayOfYear(), customComparator.getLowerLimit());
    }

    @Test
    public void testGetUpperLimit() {
        assertNull(allComparator.getUpperLimit());
        assertNull(dateOnlyComparator.getUpperLimit());
        assertEquals(DateTimeFieldType.dayOfYear(), timeOnlyComparator.getUpperLimit());
        assertEquals(DateTimeFieldType.hourOfDay(), customComparator.getUpperLimit());
    }

    @Test
    public void testEquals() {
        assertTrue(allComparator.equals(DateTimeComparator.getInstance()));
        assertTrue(dateOnlyComparator.equals(DateTimeComparator.getDateOnlyInstance()));
        assertTrue(timeOnlyComparator.equals(DateTimeComparator.getTimeOnlyInstance()));
        assertTrue(customComparator.equals(DateTimeComparator.getInstance(
            DateTimeFieldType.dayOfYear(), DateTimeFieldType.hourOfDay())));

        assertFalse(allComparator.equals(dateOnlyComparator));
        assertFalse(allComparator.equals(timeOnlyComparator));
        assertFalse(allComparator.equals(customComparator));
    }

    @Test
    public void testHashCode() {
        assertEquals(DateTimeComparator.ALL_INSTANCE.hashCode(), DateTimeComparator.getInstance().hashCode());
        assertEquals(DateTimeComparator.DATE_INSTANCE.hashCode(), DateTimeComparator.getDateOnlyInstance().hashCode());
        assertEquals(DateTimeComparator.TIME_INSTANCE.hashCode(), DateTimeComparator.getTimeOnlyInstance().hashCode());
        assertEquals(customComparator.hashCode(), DateTimeComparator.getInstance(
            DateTimeFieldType.dayOfYear(), DateTimeFieldType.hourOfDay()).hashCode());
    }

    @Test
    public void testToString() {
        assertEquals("DateTimeComparator[]", allComparator.toString());
        assertEquals("DateTimeComparator[dayOfYear]", dateOnlyComparator.toString());
        assertEquals("DateTimeComparator[dayofYear-hourOfDay]", customComparator.toString());
    }
}

