        assertEquals(1, DateTimeConstants.MONDAY);
        assertEquals(2, DateTimeConstants.TUESDAY);
        assertEquals(3, DateTimeConstants.WEDNESDAY);
        assertEquals(4, DateTimeConstants.THURSDAY);
        assertEquals(5, DateTimeConstants.FRIDAY);
        assertEquals(6, DateTimeConstants.SATURDAY);
        assertEquals(7, DateTimeConstants.SUNDAY);
    }

    @Test
    public void testAmPmConstants() {
        assertEquals(0, DateTimeConstants.AM);
        assertEquals(1, DateTimeConstants.PM);
    }

    @Test
    public void testEraConstants() {
        assertEquals(0, DateTimeConstants.BC);
        assertEquals(0, DateTimeConstants.BCE);
        assertEquals(1, DateTimeConstants.AD);
        assertEquals(1, DateTimeConstants.CE);
    }

    @Test
    public void testTimeUnitConstants() {
        assertEquals(1000, DateTimeConstants.MILLIS_PER_SECOND);
        assertEquals(60, DateTimeConstants.SECONDS_PER_MINUTE);
        assertEquals(60000, DateTimeConstants.MILLIS_PER_MINUTE);
        assertEquals(60, DateTimeConstants.MINUTES_PER_HOUR);
        assertEquals(3600, DateTimeConstants.SECONDS_PER_HOUR);
        assertEquals(3600000, DateTimeConstants.MILLIS_PER_HOUR);
        assertEquals(24, DateTimeConstants.HOURS_PER_DAY);
        assertEquals(1440, DateTimeConstants.MINUTES_PER_DAY);
        assertEquals(86400, DateTimeConstants.SECONDS_PER_DAY);
        assertEquals(86400000, DateTimeConstants.MILLIS_PER_DAY);
        assertEquals(7, DateTimeConstants.DAYS_PER_WEEK);
        assertEquals(168, DateTimeConstants.HOURS_PER_WEEK);
        assertEquals(10080, DateTimeConstants.MINUTES_PER_WEEK);
        assertEquals(604800, DateTimeConstants.SECONDS_PER_WEEK);
        assertEquals(604800000, DateTimeConstants.MILLIS_PER_WEEK);
    }

    @Test
    public void testConstructorIsProtected() {
        try {
            new DateTimeConstants();
            fail("Constructor should be protected");
        } catch (Exception e) {
            assertTrue(e instanceof java.lang.Exception);
        }
    }
}

