package org.joda.time;

import org.junit.Test;
import static org.junit.Assert.*;

public class DateTimeUtilsTest {

    @Test
    public void testCurrentTimeMillis() {
        long millis = DateTimeUtils.currentTimeMillis();
        assertTrue(millis >= 0);
    }

    @Test
    public void testSetCurrentMillisSystem() {
        try {
            DateTimeUtils.setCurrentMillisSystem();
            assertEquals(DateTimeUtils.currentTimeMillis(), System.currentTimeMillis());
        } catch (SecurityException e) {
            // Test passes if security exception is thrown
            assertTrue(true);
        }
    }

    @Test
    public void testSetCurrentMillisFixed() {
        try {
            long fixedMillis = 1234567890L;
            DateTimeUtils.setCurrentMillisFixed(fixedMillis);
            assertEquals(fixedMillis, DateTimeUtils.currentTimeMillis());
        } catch (SecurityException e) {
            // Test passes if security exception is thrown
            assertTrue(true);
        }
    }

    @Test
    public void testSetCurrentMillisOffset() {
        try {
            long offsetMillis = 1000L;
            DateTimeUtils.setCurrentMillisOffset(offsetMillis);
            long currentMillis = DateTimeUtils.currentTimeMillis();
            assertEquals(System.currentTimeMillis() + offsetMillis, currentMillis);
        } catch (SecurityException e) {
            // Test passes if security exception is thrown
            assertTrue(true);
        }
    }

    @Test
    public void testSetCurrentMillisProvider() {
        try {
            MillisProvider mockProvider = () -> 987654321L;
            DateTimeUtils.setCurrentMillisProvider(mockProvider);
            assertEquals(987654321L, DateTimeUtils.currentTimeMillis());
        } catch (SecurityException e) {
            // Test passes if security exception is thrown
            assertTrue(true);
        }
    }

    @Test
    public void testGetInstantMillis() {
        ReadableInstant instant = new Instant();
        assertEquals(instant.getMillis(), DateTimeUtils.getInstantMillis(instant));
        assertTrue(DateTimeUtils.getInstantMillis(null) >= 0);
    }

    @Test
    public void testGetInstantChronology() {
        ReadableInstant instant = new Instant();
        assertEquals(ISOChronology.getInstance(), DateTimeUtils.getInstantChronology(instant));
        assertEquals(ISOChronology.getInstance(), DateTimeUtils.getInstantChronology(null));
    }

    @Test
    public void testGetIntervalChronology() {
        ReadableInstant start = new Instant();
        ReadableInstant end = new Instant();
        assertEquals(ISOChronology.getInstance(), DateTimeUtils.getIntervalChronology(start, end));
        assertEquals(ISOChronology.getInstance(), DateTimeUtils.getIntervalChronology(null, end));
        assertEquals(ISOChronology.getInstance(), DateTimeUtils.getIntervalChronology(start, null));
        assertEquals(ISOChronology.getInstance(), DateTimeUtils.getIntervalChronology(null, null));
    }

    @Test
    public void testGetIntervalChronologyFromInterval() {
        ReadableInterval interval = new Interval();
        assertEquals(ISOChronology.getInstance(), DateTimeUtils.getIntervalChronology(interval));
        assertEquals(ISOChronology.getInstance(), DateTimeUtils.getIntervalChronology(null));
    }

    @Test
    public void testGetReadableInterval() {
        ReadableInterval interval = new Interval();
        assertEquals(interval, DateTimeUtils.getReadableInterval(interval));
        assertNotNull(DateTimeUtils.getReadableInterval(null));
    }

    @Test
    public void testGetChronology() {
        Chronology chrono = ISOChronology.getInstance();
        assertEquals(chrono, DateTimeUtils.getChronology(chrono));
        assertEquals(ISOChronology.getInstance(), DateTimeUtils.getChronology(null));
    }

    @Test
    public void testGetZone() {
        DateTimeZone zone = DateTimeZone.getDefault();
        assertEquals(zone, DateTimeUtils.getZone(zone));
        assertEquals(DateTimeZone.getDefault(), DateTimeUtils.getZone(null));
    }

    @Test
    public void testGetPeriodType() {
        PeriodType type = PeriodType.standard();
        assertEquals(type, DateTimeUtils.getPeriodType(type));
        assertEquals(PeriodType.standard(), DateTimeUtils.getPeriodType(null));
    }

    @Test
    public void testGetDurationMillis() {
        ReadableDuration duration = Duration.millis(1000);
        assertEquals(1000, DateTimeUtils.getDurationMillis(duration));
        assertEquals(0, DateTimeUtils.getDurationMillis(null));
    }

    @Test
    public void testIsContiguous() {
        ReadablePartial partial = new LocalDate();
        assertTrue(DateTimeUtils.isContiguous(partial));
        try {
            DateTimeUtils.isContiguous(null);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Partial must not be null", e.getMessage());
        }
    }

    @Test
    public void testGetDateFormatSymbols() {
        assertNotNull(DateTimeUtils.getDateFormatSymbols(null));
        assertNotNull(DateTimeUtils.getDateFormatSymbols(Locale.ENGLISH));
    }

    @Test
    public void testGetDefaultTimeZoneNames() {
        assertNotNull(DateTimeUtils.getDefaultTimeZoneNames());
    }

    @Test
    public void testSetDefaultTimeZoneNames() {
        DateTimeUtils.setDefaultTimeZoneNames(null);
        assertNotNull(DateTimeUtils.getDefaultTimeZoneNames());
    }

    @Test
    public void testToJulianDay() {
        long epochMillis = 0L;
        assertEquals(2440587.5, DateTimeUtils.toJulianDay(epochMillis), 0.0001);
    }

    @Test
    public void testToJulianDayNumber() {
        long epochMillis = 0L;
        assertEquals(2440587, DateTimeUtils.toJulianDayNumber(epochMillis));
    }

    @Test
    public void testFromJulianDay() {
        double julianDay = 2440587.5;
        assertEquals(0L, DateTimeUtils.fromJulianDay(julianDay));
    }
}

