        assertEquals(2, two.getHours());
        assertEquals("PT2H", two.toString());
    }

    @Test
    public void testThree() {
        Hours three = Hours.THREE;
        assertEquals(3, three.getHours());
        assertEquals("PT3H", three.toString());
    }

    @Test
    public void testFour() {
        Hours four = Hours.FOUR;
        assertEquals(4, four.getHours());
        assertEquals("PT4H", four.toString());
    }

    @Test
    public void testFive() {
        Hours five = Hours.FIVE;
        assertEquals(5, five.getHours());
        assertEquals("PT5H", five.toString());
    }

    @Test
    public void testSix() {
        Hours six = Hours.SIX;
        assertEquals(6, six.getHours());
        assertEquals("PT6H", six.toString());
    }

    @Test
    public void testSeven() {
        Hours seven = Hours.SEVEN;
        assertEquals(7, seven.getHours());
        assertEquals("PT7H", seven.toString());
    }

