    public void testEight() {
        Hours eight = Hours.EIGHT;
        assertEquals(8, eight.getHours());
        assertEquals("PT8H", eight.toString());
    }

    @Test
    public void testMaxValue() {
        Hours max = Hours.MAX_VALUE;
        assertEquals(Integer.MAX_VALUE, max.getHours());
        assertEquals("PT" + Integer.MAX_VALUE + "H", max.toString());
    }

    @Test
    public void testMinValue() {
        Hours min = Hours.MIN_VALUE;
        assertEquals(Integer.MIN_VALUE, min.getHours());
        assertEquals("PT" + Integer.MIN_VALUE + "H", min.toString());
    }

    @Test
    public void testHours() {
        for (int i = -100; i <= 100; i++) {
            Hours hours = Hours.hours(i);
            assertEquals(i, hours.getHours());
            assertEquals("PT" + i + "H", hours.toString());
        }
    }

    @Test
    public void testPlus() {
        Hours base = Hours.hours(10);
        assertEquals(15, base.plus(5).getHours());
        assertEquals(5, base.plus(-5).getHours());
        assertEquals(10, base.plus(0).getHours());
    }

    @Test
    public void testMinus() {
        Hours base = Hours.hours(10);
        assertEquals(5, base.minus(5).getHours());
        assertEquals(15, base.minus(-5).getHours());
        assertEquals(10, base.minus(0).getHours());
    }

