        Hours base = Hours.hours(10);
        assertTrue(base.isGreaterThan(Hours.hours(5)));
        assertFalse(base.isGreaterThan(Hours.hours(10)));
        assertFalse(base.isGreaterThan(Hours.hours(15)));
        assertFalse(base.isGreaterThan(null));
    }

