package org.joda.time;

import org.junit.Test;
import static org.junit.Assert.*;

public class IllegalInstantExceptionTest {

    @Test
    public void testConstructorWithMessage() {
        String message = "Test message";
        IllegalInstantException exception = new IllegalInstantException(message);
        assertEquals(message, exception.getMessage());
    }

    @Test
    public void testConstructorWithInstantAndZoneId() {
        long instantLocal = 1234567890000L;
        String zoneId = "America/New_York";
        IllegalInstantException exception = new IllegalInstantException(instantLocal, zoneId);
        assertTrue(exception.getMessage().contains("Illegal instant due to time zone offset transition"));
        assertTrue(exception.getMessage().contains("1970-02-13T21:31:38.900 (America/New_York)"));
    }

    @Test
    public void testConstructorWithInstantAndNullZoneId() {
        long instantLocal = 1234567890000L;
        IllegalInstantException exception = new IllegalInstantException(instantLocal, null);
        assertTrue(exception.getMessage().contains("Illegal instant due to time zone offset transition"));
        assertTrue(exception.getMessage().contains("1970-02-13T21:31:38.900"));
    }

    @Test
    public void testIsIllegalInstantWithSameException() {
        IllegalInstantException exception = new IllegalInstantException("Test message");
        assertTrue(IllegalInstantException.isIllegalInstant(exception));
    }

    @Test
    public void testIsIllegalInstantWithCause() {
        IllegalInstantException cause = new IllegalInstantException("Cause message");
        RuntimeException exception = new RuntimeException("Test message", cause);
        assertTrue(IllegalInstantException.isIllegalInstant(exception));
    }

    @Test
    public void testIsIllegalInstantWithDifferentException() {
        RuntimeException exception = new RuntimeException("Test message");
        assertFalse(IllegalInstantException.isIllegalInstant(exception));
    }

    @Test
    public void testIsIllegalInstantWithNull() {
        assertFalse(IllegalInstantException.isIllegalInstant(null));
    }

    @Test
    public void testIsIllegalInstantWithNestedCauses() {
        IllegalInstantException cause1 = new IllegalInstantException("Cause 1");
        RuntimeException cause2 = new RuntimeException("Cause 2", cause1);
        RuntimeException exception = new RuntimeException("Test message", cause2);
        assertTrue(IllegalInstantException.isIllegalInstant(exception));
    }
}

