package org.joda.time;

import org.junit.Test;
import static org.junit.Assert.*;

public class InstantTest {

    @Test
    public void testNow() {
        Instant now = Instant.now();
        assertNotNull(now);
        assertTrue(now.getMillis() >= 0);
    }

    @Test
    public void testOfEpochMilli() {
        long testMillis = 1234567890L;
        Instant instant = Instant.ofEpochMilli(testMillis);
        assertEquals(testMillis, instant.getMillis());
    }

    @Test
    public void testOfEpochSecond() {
        long testSeconds = 123456L;
        Instant instant = Instant.ofEpochSecond(testSeconds);
        assertEquals(testSeconds * 1000, instant.getMillis());
    }

    @Test(expected = ArithmeticException.class)
    public void testOfEpochSecondOverflow() {
        Instant.ofEpochSecond(Long.MAX_VALUE);
    }

    @Test
    public void testParse() {
        String testString = "2007-12-03T10:15:30";
        Instant instant = Instant.parse(testString);
        assertEquals("2007-12-03T10:15:30.000Z", instant.toString());
    }

    @Test
    public void testParseWithFormatter() {
        String testString = "2007-12-03";
        Instant instant = Instant.parse(testString, ISODateTimeFormat.date());
        assertEquals("2007-12-03T00:00:00.000Z", instant.toString());
    }

    @Test
    public void testConstructorWithMillis() {
        long testMillis = 1234567890L;
        Instant instant = new Instant(testMillis);
        assertEquals(testMillis, instant.getMillis());
    }

    @Test
    public void testConstructorWithObject() {
        String testString = "2007-12-03T10:15:30";
        Instant instant = new Instant(testString);
        assertEquals("2007-12-03T10:15:30.000Z", instant.toString());
    }

    @Test
    public void testToInstant() {
        Instant original = Instant.now();
        Instant converted = original.toInstant();
        assertSame(original, converted);
    }

    @Test
    public void testWithMillisSameValue() {
        Instant original = Instant.now();
        Instant modified = original.withMillis(original.getMillis());
        assertSame(original, modified);
    }

    @Test
    public void testWithMillisDifferentValue() {
        Instant original = Instant.now();
        long newMillis = original.getMillis() + 1000;
        Instant modified = original.withMillis(newMillis);
        assertNotSame(original, modified);
        assertEquals(newMillis, modified.getMillis());
    }

    @Test
    public void testWithDurationAddedZero() {
        Instant original = Instant.now();
        Instant modified = original.withDurationAdded(0, 1);
        assertSame(original, modified);
    }

    @Test
    public void testWithDurationAddedPositive() {
        Instant original = Instant.now();
        long duration = 1000;
        Instant modified = original.withDurationAdded(duration, 1);
        assertNotSame(original, modified);
        assertEquals(original.getMillis() + duration, modified.getMillis());
    }

    @Test
    public void testWithDurationAddedNegative() {
        Instant original = Instant.now();
        long duration = 1000;
        Instant modified = original.withDurationAdded(duration, -1);
        assertNotSame(original, modified);
        assertEquals(original.getMillis() - duration, modified.getMillis());
    }

    @Test
    public void testWithDurationAddedReadableDuration() {
        Instant original = Instant.now();
        ReadableDuration duration = Duration.millis(1000);
        Instant modified = original.withDurationAdded(duration, 1);
        assertNotSame(original, modified);
        assertEquals(original.getMillis() + 1000, modified.getMillis());
    }

    @Test
    public void testPlus() {
        Instant original = Instant.now();
        long duration = 1000;
        Instant modified = original.plus(duration);
        assertNotSame(original, modified);
        assertEquals(original.getMillis() + duration, modified.getMillis());
    }

    @Test
    public void testMinus() {
        Instant original = Instant.now();
        long duration = 1000;
        Instant modified = original.minus(duration);
        assertNotSame(original, modified);
        assertEquals(original.getMillis() - duration, modified.getMillis());
    }

    @Test
    public void testGetMillis() {
        long testMillis = 1234567890L;
        Instant instant = new Instant(testMillis);
        assertEquals(testMillis, instant.getMillis());
    }

    @Test
    public void testGetChronology() {
        Instant instant = Instant.now();
        assertEquals(ISOChronology.getInstanceUTC(), instant.getChronology());
    }

    @Test
    public void testToDateTime() {
        Instant instant = Instant.now();
        DateTime dateTime = instant.toDateTime();
        assertEquals(instant.getMillis(), dateTime.getMillis());
    }

    @Test
    public void testToMutableDateTime() {
        Instant instant = Instant.now();
        MutableDateTime mutableDateTime = instant.toMutableDateTime();
        assertEquals(instant.getMillis(), mutableDateTime.getMillis());
    }

    @Test
    public void testEquals() {
        Instant instant1 = Instant.now();
        Instant instant2 = new Instant(instant1.getMillis());
        assertEquals(instant1, instant2);
    }

    @Test
    public void testNotEquals() {
        Instant instant1 = Instant.now();
        Instant instant2 = new Instant(instant1.getMillis() + 1);
        assertNotEquals(instant1, instant2);
    }

    @Test
    public void testCompareTo() {
        Instant earlier = new Instant(1000);
        Instant later = new Instant(2000);
        assertTrue(earlier.compareTo(later) < 0);
        assertTrue(later.compareTo(earlier) > 0);
        assertEquals(0, earlier.compareTo(earlier));
    }

    @Test
    public void testIsEqual() {
        Instant instant1 = Instant.now();
        Instant instant2 = new Instant(instant1.getMillis());
        assertTrue(instant1.isEqual(instant2));
    }

    @Test
    public void testIsAfter() {
        Instant earlier = new Instant(1000);
        Instant later = new Instant(2000);
        assertTrue(later.isAfter(earlier));
    }

    @Test
    public void testIsBefore() {
        Instant earlier = new Instant(1000);
        Instant later = new Instant(2000);
        assertTrue(earlier.isBefore(later));
    }

    @Test
    public void testToString() {
        Instant instant = new Instant(1234567890L);
        assertEquals("1970-01-14T21:31:30.789Z", instant.toString());
    }
}

