package org.joda.time;

import org.junit.Test;
import static org.junit.Assert.*;

public class IntervalTest {

    @Test
    public void testParse() {
        String intervalStr = "2010-06-30T01:20/P1D";
        Interval interval = Interval.parse(intervalStr);
        assertEquals(2010, interval.getStart().getYear());
        assertEquals(6, interval.getStart().getMonthOfYear());
        assertEquals(30, interval.getStart().getDayOfMonth());
        assertEquals(1, interval.getStart().getHourOfDay());
        assertEquals(20, interval.getStart().getMinuteOfHour());
        assertEquals(0, interval.getStart().getSecondOfMinute());
        assertEquals(0, interval.getStart().getMillisOfSecond());
        assertEquals(2010, interval.getEnd().getYear());
        assertEquals(7, interval.getEnd().getMonthOfYear());
        assertEquals(1, interval.getEnd().getDayOfMonth());
        assertEquals(1, interval.getEnd().getHourOfDay());
        assertEquals(20, interval.getEnd().getMinuteOfHour());
        assertEquals(0, interval.getEnd().getSecondOfMinute());
        assertEquals(0, interval.getEnd().getMillisOfSecond());
    }

    @Test
    public void testParseWithOffset() {
        String intervalStr = "2010-06-30T01:20+02:00/P1D";
        Interval interval = Interval.parseWithOffset(intervalStr);
        assertEquals(2010, interval.getStart().getYear());
        assertEquals(6, interval.getStart().getMonthOfYear());
        assertEquals(30, interval.getStart().getDayOfMonth());
        assertEquals(1, interval.getStart().getHourOfDay());
        assertEquals(20, interval.getStart().getMinuteOfHour());
        assertEquals(0, interval.getStart().getSecondOfMinute());
        assertEquals(0, interval.getStart().getMillisOfSecond());
        assertEquals(DateTimeZone.forOffsetHours(2), interval.getStart().getZone());
        assertEquals(2010, interval.getEnd().getYear());
        assertEquals(7, interval.getEnd().getMonthOfYear());
        assertEquals(1, interval.getEnd().getDayOfMonth());
        assertEquals(1, interval.getEnd().getHourOfDay());
        assertEquals(20, interval.getEnd().getMinuteOfHour());
        assertEquals(0, interval.getEnd().getSecondOfMinute());
        assertEquals(0, interval.getEnd().getMillisOfSecond());
        assertEquals(DateTimeZone.forOffsetHours(2), interval.getEnd().getZone());
    }

    @Test
    public void testConstructorWithMillis() {
        long startMillis = 1277852000000L; // 2010-06-30T01:20:00.000Z
        long endMillis = 1277938400000L; // 2010-07-01T01:20:00.000Z
        Interval interval = new Interval(startMillis, endMillis);
        assertEquals(startMillis, interval.getStartMillis());
        assertEquals(endMillis, interval.getEndMillis());
        assertEquals(ISOChronology.getInstanceUTC(), interval.getChronology());
    }

    @Test
    public void testConstructorWithMillisAndZone() {
        long startMillis = 1277852000000L; // 2010-06-30T01:20:00.000Z
        long endMillis = 1277938400000L; // 2010-07-01T01:20:00.000Z
        DateTimeZone zone = DateTimeZone.forOffsetHours(2);
        Interval interval = new Interval(startMillis, endMillis, zone);
        assertEquals(startMillis, interval.getStartMillis());
        assertEquals(endMillis, interval.getEndMillis());
        assertEquals(zone, interval.getChronology().getZone());
    }

    @Test
    public void testConstructorWithInstant() {
        DateTime start = new DateTime(2010, 6, 30, 1, 20, 0, 0);
        DateTime end = new DateTime(2010, 7, 1, 1, 20, 0, 0);
        Interval interval = new Interval(start, end);
        assertEquals(start.getMillis(), interval.getStartMillis());
        assertEquals(end.getMillis(), interval.getEndMillis());
        assertEquals(start.getChronology(), interval.getChronology());
    }

    @Test
    public void testConstructorWithDuration() {
        DateTime start = new DateTime(2010, 6, 30, 1, 20, 0, 0);
        Duration duration = new Duration(24 * 60 * 60 * 1000); // 1 day
        Interval interval = new Interval(start, duration);
        assertEquals(start.getMillis(), interval.getStartMillis());
        assertEquals(start.getMillis() + duration.getMillis(), interval.getEndMillis());
        assertEquals(start.getChronology(), interval.getChronology());
    }

    @Test
    public void testConstructorWithPeriod() {
        DateTime start = new DateTime(2010, 6, 30, 1, 20, 0, 0);
        Period period = new Period(1, 0, 0, 0); // 1 day
        Interval interval = new Interval(start, period);
        assertEquals(start.getMillis(), interval.getStartMillis());
        assertEquals(start.getMillis() + period.toStandardDuration().getMillis(), interval.getEndMillis());
        assertEquals(start.getChronology(), interval.getChronology());
    }

    @Test
    public void testOverlap() {
        Interval interval1 = new Interval(1277852000000L, 1277938400000L); // 2010-06-30T01:20:00.000Z to 2010-07-01T01:20:00.000Z
        Interval interval2 = new Interval(1277938400000L, 1278024800000L); // 2010-07-01T01:20:00.000Z to 2010-07-02T01:20:00.000Z
        Interval overlap = interval1.overlap(interval2);
        assertNotNull(overlap);
        assertEquals(1277938400000L, overlap.getStartMillis());
        assertEquals(1277938400000L, overlap.getEndMillis());
    }

    @Test
    public void testGap() {
        Interval interval1 = new Interval(1277852000000L, 1277938400000L); // 2010-06-30T01:20:00.000Z to 2010-07-01T01:20:00.000Z
        Interval interval2 = new Interval(1278024800000L, 1278111200000L); // 2010-07-02T01:20:00.000Z to 2010-07-03T01:20:00.000Z
        Interval gap = interval1.gap(interval2);
        assertNotNull(gap);
        assertEquals(1277938400000L, gap.getStartMillis());
        assertEquals(1278024800000L, gap.getEndMillis());
    }

    @Test
    public void testAbuts() {
        Interval interval1 = new Interval(1277852000000L, 1277938400000L); // 2010-06-30T01:20:00.000Z to 2010-07-01T01:20:00.000Z
        Interval interval2 = new Interval(1277938400000L, 1278024800000L); // 2010-07-01T01:20:00.000Z to 2010-07-02T01:20:00.000Z
        assertTrue(interval1.abuts(interval2));
    }

    @Test
    public void testWithChronology() {
        Interval interval = new Interval(1277852000000L, 1277938400000L);
        DateTimeZone zone = DateTimeZone.forOffsetHours(2);
        Interval newInterval = interval.withChronology(zone);
        assertNotSame(interval, newInterval);
        assertEquals(zone, newInterval.getChronology().getZone());
    }

    @Test
    public void testWithStartMillis() {
        Interval interval = new Interval(1277852000000L, 1277938400000L);
        long newStartMillis = 1277855600000L; // 2010-06-30T02:00:00.000Z
        Interval newInterval = interval.withStartMillis(newStartMillis);
        assertNotSame(interval, newInterval);
        assertEquals(newStartMillis, newInterval.getStartMillis());
    }

    @Test
    public void testWithEndMillis() {
        Interval interval = new Interval(1277852000000L, 1277938400000L);
        long newEndMillis = 1277942000000L; // 2010-07-01T02:00:00.000Z
