package org.joda.time;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import java.security.BasicPermission;
import java.security.Permission;
import java.security.PermissionCollection;
import java.security.Permissions;
import java.security.SecurityManager;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.Mockito;
import org.mockito.runners.MockitoJUnitRunner;

@RunWith(MockitoJUnitRunner.class)
public class JodaTimePermissionTest {

    @Mock
    private SecurityManager mockSecurityManager;

    @Test
    public void testConstructorWithNullName() {
        try {
            new JodaTimePermission(null);
            assertTrue("Expected IllegalArgumentException for null name", false);
        } catch (IllegalArgumentException e) {
            assertEquals("The name must not be null", e.getMessage());
        }
    }

    @Test
    public void testConstructorWithEmptyName() {
        JodaTimePermission permission = new JodaTimePermission("");
        assertNotNull("Permission should not be null", permission);
    }

    @Test
    public void testConstructorWithValidName() {
        JodaTimePermission permission = new JodaTimePermission("DateTimeZone.setDefault");
        assertNotNull("Permission should not be null", permission);
        assertEquals("DateTimeZone.setDefault", permission.getName());
    }

    @Test
    public void testImplicitPermission() {
        JodaTimePermission permission = new JodaTimePermission("DateTimeZone.setDefault");
        assertTrue("Permission should be implicit", permission.getActions().isEmpty());
    }

    @Test
    public void testPermissionCollection() {
        PermissionCollection permissions = new Permissions();
        permissions.add(new JodaTimePermission("DateTimeZone.setDefault"));
        permissions.add(new JodaTimePermission("DateTimeZone.setProvider"));

        assertEquals(2, permissions.size());
    }

    @Test
    public void testEquals() {
        JodaTimePermission permission1 = new JodaTimePermission("DateTimeZone.setDefault");
        JodaTimePermission permission2 = new JodaTimePermission("DateTimeZone.setDefault");
        JodaTimePermission permission3 = new JodaTimePermission("DateTimeZone.setProvider");

        assertEquals("Permissions with same name should be equal", permission1, permission2);
        assertTrue("Permissions with different names should not be equal", !permission1.equals(permission3));
        assertTrue("Permission should not equal null", !permission1.equals(null));
        assertTrue("Permission should not equal different type", !permission1.equals(new Object()));
    }

    @Test
    public void testHashCode() {
        JodaTimePermission permission1 = new JodaTimePermission("DateTimeZone.setDefault");
        JodaTimePermission permission2 = new JodaTimePermission("DateTimeZone.setDefault");
        JodaTimePermission permission3 = new JodaTimePermission("DateTimeZone.setProvider");

        assertEquals("Hash codes for equal permissions should be equal",
                    permission1.hashCode(), permission2.hashCode());
        assertTrue("Hash codes for different permissions should not be equal",
                  permission1.hashCode() != permission3.hashCode());
    }

    @Test
    public void testToString() {
        JodaTimePermission permission = new JodaTimePermission("DateTimeZone.setDefault");
        assertEquals("DateTimeZone.setDefault", permission.toString());
    }

    @Test
    public void testSecurityCheckPass() {
        Mockito.when(mockSecurityManager.checkPermission(Mockito.any(Permission.class))).thenReturn(true);

        SecurityManager original = System.getSecurityManager();
        try {
            System.setSecurityManager(mockSecurityManager);
            // This should not throw an exception
            new JodaTimePermission("DateTimeZone.setDefault");
        } finally {
            System.setSecurityManager(original);
        }
    }

    @Test
    public void testSecurityCheckFail() {
        Mockito.when(mockSecurityManager.checkPermission(Mockito.any(Permission.class)))
               .thenThrow(new SecurityException("Security violation"));

        SecurityManager original = System.getSecurityManager();
        try {
            System.setSecurityManager(mockSecurityManager);
            try {
                new JodaTimePermission("DateTimeZone.setDefault");
                assertTrue("Expected SecurityException", false);
            } catch (SecurityException e) {
                assertEquals("Security violation", e.getMessage());
            }
        } finally {
            System.setSecurityManager(original);
        }
    }
}

