package org.joda.time;

import org.junit.Test;
import static org.junit.Assert.*;

public class LocalDateTest {

    @Test
    public void testNow() {
        LocalDate date = LocalDate.now();
        assertNotNull(date);
    }

    @Test
    public void testNowWithZone() {
        LocalDate date = LocalDate.now(DateTimeZone.UTC);
        assertNotNull(date);
        assertEquals(DateTimeZone.UTC, date.getChronology().getZone());
    }

    @Test
    public void testNowWithChronology() {
        LocalDate date = LocalDate.now(ISOChronology.getInstanceUTC());
        assertNotNull(date);
        assertEquals(ISOChronology.getInstanceUTC(), date.getChronology());
    }

    @Test
    public void testParse() {
        LocalDate date = LocalDate.parse("2023-05-15");
        assertNotNull(date);
        assertEquals(2023, date.getYear());
        assertEquals(5, date.getMonthOfYear());
        assertEquals(15, date.getDayOfMonth());
    }

    @Test
    public void testParseWithFormatter() {
        LocalDate date = LocalDate.parse("15/05/2023", DateTimeFormat.forPattern("dd/MM/yyyy"));
        assertNotNull(date);
        assertEquals(2023, date.getYear());
        assertEquals(5, date.getMonthOfYear());
        assertEquals(15, date.getDayOfMonth());
    }

    @Test
    public void testFromCalendarFields() {
        java.util.Calendar calendar = java.util.Calendar.getInstance();
        calendar.set(2023, java.util.Calendar.MAY, 15);
        LocalDate date = LocalDate.fromCalendarFields(calendar);
        assertNotNull(date);
        assertEquals(2023, date.getYear());
        assertEquals(5, date.getMonthOfYear());
        assertEquals(15, date.getDayOfMonth());
    }

    @Test
    public void testFromDateFields() {
        java.util.Date date = new java.util.Date(1684137600000L);
        LocalDate localDate = LocalDate.fromDateFields(date);
        assertNotNull(localDate);
        assertEquals(2023, localDate.getYear());
        assertEquals(5, localDate.getMonthOfYear());
        assertEquals(15, localDate.getDayOfMonth());
    }

    @Test
    public void testConstructorWithYearMonthDay() {
        LocalDate date = new LocalDate(2023, 5, 15);
        assertNotNull(date);
        assertEquals(2023, date.getYear());
        assertEquals(5, date.getMonthOfYear());
        assertEquals(15, date.getDayOfMonth());
    }

    @Test
    public void testConstructorWithYearMonthDayChronology() {
        LocalDate date = new LocalDate(2023, 5, 15, ISOChronology.getInstanceUTC());
        assertNotNull(date);
        assertEquals(2023, date.getYear());
        assertEquals(5, date.getMonthOfYear());
        assertEquals(15, date.getDayOfMonth());
        assertEquals(ISOChronology.getInstanceUTC(), date.getChronology());
    }

    @Test
    public void testEquals() {
        LocalDate date1 = new LocalDate(2023, 5, 15);
        LocalDate date2 = new LocalDate(2023, 5, 15);
        assertEquals(date1, date2);
    }

    @Test
    public void testNotEquals() {
        LocalDate date1 = new LocalDate(2023, 5, 15);
        LocalDate date2 = new LocalDate(2023, 5, 16);
        assertNotEquals(date1, date2);
    }

    @Test
    public void testCompareTo() {
        LocalDate date1 = new LocalDate(2023, 5, 15);
        LocalDate date2 = new LocalDate(2023, 5, 16);
        assertTrue(date1.compareTo(date2) < 0);
    }

    @Test
    public void testToDateTimeAtStartOfDay() {
        LocalDate date = new LocalDate(2023, 5, 15);
        DateTime dateTime = date.toDateTimeAtStartOfDay();
        assertNotNull(dateTime);
        assertEquals(2023, dateTime.getYear());
        assertEquals(5, dateTime.getMonthOfYear());
        assertEquals(15, dateTime.getDayOfMonth());
        assertEquals(0, dateTime.getHourOfDay());
        assertEquals(0, dateTime.getMinuteOfHour());
        assertEquals(0, dateTime.getSecondOfMinute());
        assertEquals(0, dateTime.getMillisOfSecond());
    }

    @Test
    public void testToDateTimeAtStartOfDayWithZone() {
        LocalDate date = new LocalDate(2023, 5, 15);
        DateTime dateTime = date.toDateTimeAtStartOfDay(DateTimeZone.UTC);
        assertNotNull(dateTime);
        assertEquals(2023, dateTime.getYear());
        assertEquals(5, dateTime.getMonthOfYear());
        assertEquals(15, dateTime.getDayOfMonth());
        assertEquals(0, dateTime.getHourOfDay());
        assertEquals(0, dateTime.getMinuteOfHour());
        assertEquals(0, dateTime.getSecondOfMinute());
        assertEquals(0, dateTime.getMillisOfSecond());
        assertEquals(DateTimeZone.UTC, dateTime.getZone());
    }

    @Test
    public void testToDateTimeAtCurrentTime() {
        LocalDate date = new LocalDate(2023, 5, 15);
        DateTime dateTime = date.toDateTimeAtCurrentTime();
        assertNotNull(dateTime);
        assertEquals(2023, dateTime.getYear());
        assertEquals(5, dateTime.getMonthOfYear());
        assertEquals(15, dateTime.getDayOfMonth());
    }

    @Test
    public void testToDateTimeAtCurrentTimeWithZone() {
        LocalDate date = new LocalDate(2023, 5, 15);
        DateTime dateTime = date.toDateTimeAtCurrentTime(DateTimeZone.UTC);
        assertNotNull(dateTime);
        assertEquals(2023, dateTime.getYear());
        assertEquals(5, dateTime.getMonthOfYear());
        assertEquals(15, dateTime.getDayOfMonth());
        assertEquals(DateTimeZone.UTC, dateTime.getZone());
    }

    @Test
    public void testToLocalDateTime() {
        LocalDate date = new LocalDate(2023, 5, 15);
        LocalTime time = new LocalTime(12, 30, 45);
        LocalDateTime dateTime = date.toLocalDateTime(time);
        assertNotNull(dateTime);
        assertEquals(2023, dateTime.getYear());
        assertEquals(5, dateTime.getMonthOfYear());
        assertEquals(15, dateTime.getDayOfMonth());
        assertEquals(12, dateTime.getHourOfDay());
        assertEquals(30, dateTime.getMinuteOfHour());
        assertEquals(45, dateTime.getSecondOfMinute());
    }

    @Test
    public void testToDateTime() {
        LocalDate date = new LocalDate(2023, 5, 15);
        LocalTime time = new LocalTime(12, 30, 45);
        DateTime dateTime = date.toDateTime(time);
        assertNotNull(dateTime);
        assertEquals(2023, dateTime.getYear());
        assertEquals(5, dateTime.getMonthOfYear());
        assertEquals(15, dateTime.getDayOfMonth());
        assertEquals(12, dateTime.getHourOfDay());
        assertEquals(30, dateTime.getMinuteOfHour());
        assertEquals(45, dateTime.getSecondOfMinute());
    }

    @Test
    public void testToDateTimeWithZone() {
        LocalDate date = new LocalDate(2023, 5, 15);
        LocalTime time = new LocalTime(12, 30, 45);
        DateTime dateTime = date.toDateTime(time, DateTimeZone.UTC);
        assertNotNull(dateTime);
        assertEquals(2023, dateTime.getYear());
        assertEquals(5, dateTime.getMonthOfYear());
        assertEquals(15, dateTime.getDayOfMonth());
        assertEquals(12, dateTime.getHourOfDay());
        assertEquals(30, dateTime.getMinuteOfHour());
        assertEquals(45, dateTime.getSecondOfMinute());
        assertEquals(DateTimeZone.UTC, dateTime.getZone());
    }

    @Test
    public void testToInterval() {
        LocalDate date = new LocalDate(2023, 5, 15);
        Interval interval = date.toInterval();
        assertNotNull(interval);
        assertEquals(2023, interval.getStart().getYear());
        assertEquals(5, interval.getStart().getMonthOfYear());
        assertEquals(15, interval.getStart().getDayOfMonth());
        assertEquals(2023, interval.getEnd().getYear());
        assertEquals(5, interval.getEnd().getMonthOfYear());
