        Property property = dateTime.millisOfSecond();
        assertNotNull(property);
        assertEquals(dateTime.getMillisOfSecond(), property.get());
    }

    @Test
    public void testCopy() {
        MutableDateTime dateTime = new MutableDateTime();
        MutableDateTime copy = dateTime.copy();
        assertNotNull(copy);
        assertEquals(dateTime.getMillis(), copy.getMillis());
        assertEquals(dateTime.getChronology(), copy.getChronology());
    }

    @Test
    public void testClone() {
        MutableDateTime dateTime = new MutableDateTime();
        MutableDateTime clone = dateTime.clone();
        assertNotNull(clone);
        assertEquals(dateTime.getMillis(), clone.getMillis());
        assertEquals(dateTime.getChronology(), clone.getChronology());
    }
}
